<script lang="ts">
 import {onMount,onDestroy,createEventDispatcher} from 'svelte';
 export let companyId:string;export let attachment:{id:string;url:string;name?:string};export let accessSignal:AbortSignal;
 const dispatch=createEventDispatcher();let ready=false,scope='',bound:AbortSignal|undefined,controller:AbortController|null=null,blobUrl='',loading=true,error='',epoch=0;
 function clear(){epoch++;controller?.abort();controller=null;if(blobUrl)URL.revokeObjectURL(blobUrl);blobUrl='';}
 function revoked(){clear();loading=false;error='Image access changed.';}
 $: nextScope=JSON.stringify([companyId,attachment?.id,attachment?.url]);
 $: if(ready&&(scope!==nextScope||bound!==accessSignal)){bound?.removeEventListener('abort',revoked);bound=accessSignal;bound?.addEventListener('abort',revoked,{once:true});scope=nextScope;void load();}
 async function load(){clear();loading=true;error='';const version=epoch,token=localStorage.token||'',prefix='/api/v1/companies/'+encodeURIComponent(companyId)+'/generated-images/';
  if(!attachment?.url?.startsWith(prefix)||!/^[-a-zA-Z0-9]{1,128}\/content$/.test(attachment.url.slice(prefix.length))||accessSignal.aborted){loading=false;error='Image is unavailable in this company.';return;}
  const current=controller=new AbortController();try{const response=await fetch(attachment.url,{signal:current.signal,credentials:'same-origin',cache:'no-store',headers:{Authorization:'Bearer '+token,Accept:'image/png'}});if(!response.ok)throw Error(response.status===403||response.status===401?'Image access is unavailable.':'Image could not be loaded.');if(response.headers.get('content-type')?.split(';')[0]!=='image/png')throw Error('Unexpected image format.');const blob=await response.blob();if(blob.size>25*1024*1024)throw Error('Image is too large to preview.');if(version!==epoch||accessSignal.aborted||token!==(localStorage.token||''))return;blobUrl=URL.createObjectURL(blob);}catch(cause){if(version===epoch&&!current.signal.aborted)error=(cause as Error).message;}finally{if(version===epoch)loading=false;}}
 function session(event:StorageEvent){if(event.key==='token'||event.key===null)revoked();}
 onMount(()=>{ready=true;window.addEventListener('storage',session);});onDestroy(()=>{clear();bound?.removeEventListener('abort',revoked);window.removeEventListener('storage',session);});
</script>
<figure class="generated-image">{#if loading}<p role="status">Loading generated image…</p>{:else if error}<p role="alert">{error}</p>{:else if blobUrl}<img src={blobUrl} alt={attachment.name||'Generated image'} loading="lazy"/><figcaption><span>{attachment.name||'Generated image'}</span><a href={blobUrl} download={attachment.name||'Generated image.png'}>Download image</a></figcaption>{/if}</figure>
<style>.generated-image{margin:16px 0;border:1px solid #dfe7f2;border-radius:12px;overflow:hidden;background:#f8faff;max-width:100%;white-space:normal}.generated-image img{display:block;width:100%;max-height:560px;object-fit:contain;background:#f1f5fc}.generated-image figcaption{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;padding:12px 14px;font-size:12px;color:#526780}.generated-image a{color:#1d4ed8;font-weight:600;text-decoration:none}.generated-image a:focus-visible{outline:2px solid #2563eb;outline-offset:3px}.generated-image p{padding:20px;font-size:12px;color:#526780;margin:0}</style>
